// Settings for Screener: Daily Sweep (spec §7 freshness · §10.2 item 7b). DRY_RUN plans everything and
// reports it in Slack but writes nothing to GHL: use it for the first real runs.
const DRY_RUN = false;
const MAX_CONTACTS = 50;        // contacts changed per run at most; the rest wait for tomorrow (reported)
const STALE_DAYS = 14;          // Date Screened older than this = stale (Kevin, ~25:20)
const SCREENER_USER_ID = '';    // GHL user a re-screened lead is assigned to (the screener); '' = unassigned, reported
const now = Date.now();
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Los_Angeles' }).format(new Date(now));
return [{ json: { dry_run: DRY_RUN, max_contacts: MAX_CONTACTS, stale_days: STALE_DAYS, screener_user_id: SCREENER_USER_ID, now_ms: now, today_pt: today } }];

// The screener opportunities the sweep looks at, one GHL search each (100 per search; a full page is
// reported as truncated so nobody mistakes it for "all done").
const BASE = 'https://services.leadconnectorhq.com/opportunities/search?location_id=rzaMhqeo2apNI1p6DG5z&pipeline_id=CvDwpavqkHSRhg5Bn3L4&limit=100';
return [
  { label: 'Gatekeeper', url: BASE + '&status=open&pipeline_stage_id=f83777fa-1dc0-4163-aa84-ef501126d82b' },
  { label: 'Not Sure', url: BASE + '&status=open&pipeline_stage_id=0c160182-e74d-4ace-9d3b-c4404043ef4b' },
  { label: 'Exhausted', url: BASE + '&status=open&pipeline_stage_id=c1db8172-84bf-45a1-8f0e-5625157574a5' },
  { label: 'graduated', url: BASE + '&status=won' }
].map(json => ({ json }));

// One entry per contact the sweep must look at: tagged owner-confirmed (the hour-block lists), or with a
// screener opportunity in Gatekeeper / Not Sure / Exhausted, or graduated (won). A failed search is
// reported, never read as "nothing to do".
const s = v => String(v == null ? '' : v).trim();
const err = j => s(j.error.message || JSON.stringify(j.error)).slice(0, 200);
const PAGE = 100;
const found = new Map();
const add = (id, from) => { id = s(id); if (!id) return; if (!found.has(id)) found.set(id, []); if (!found.get(id).includes(from)) found.get(id).push(from); };
const search_errors = [], truncated = [];
const cs = $('GHL: owner-confirmed contacts').first().json || {};
if (cs.error) search_errors.push('owner-confirmed contacts: ' + err(cs));
else { (cs.contacts || []).forEach(c => add(c.id, 'owner-confirmed')); if ((cs.contacts || []).length >= PAGE) truncated.push('owner-confirmed'); }
const labels = $('Stale searches').all().map(i => i.json.label);
$('GHL: screener opps').all().forEach((it, i) => {
  const j = it.json || {}, label = labels[i] || '?';
  if (j.error) { search_errors.push(label + ': ' + err(j)); return; }
  const list = j.opportunities || [];
  list.forEach(o => add(o.contactId || (o.contact && o.contact.id), label));
  if (list.length >= PAGE) truncated.push(label);
});
// A contact whose earlier sweep half failed is always re-read, whatever stage it is in now.
(() => { try { return $('Pending sweeps').all().map(i => i.json); } catch (e) { return []; } })()
  .filter(r => r && r.contact_id).forEach(r => add(r.contact_id, 'pending retry'));
return [{ json: { contact_ids: [...found.keys()], sources: Object.fromEntries(found), search_errors, truncated } }];

// The daily sweep for one contact (spec §7 freshness, §8 re-screen trap; decisions 2026-09-25):
//  1. Expire: Date Screened older than STALE_DAYS -> owner-confirmed, the screened-pt tag and the block
//     followers come off (every open opportunity, Kevin's too), so the lead drops out of Kevin's
//     hour-block lists. It stays in his normal cadence.
//  2. Re-screen: Gatekeeper / Not Sure / graduated owner older than STALE_DAYS, or Exhausted for longer
//     than STALE_DAYS -> fields cleared, result tags off, screening on, screener opportunity back in
//     Attempt 1. Never with an open opportunity in Kevin's pipelines (it would switch his automations
//     off for the lead), never for a DND contact, never for Disqualified.
const SCREENER = 'CvDwpavqkHSRhg5Bn3L4';
const ST = { attempt1: '7ff9193f-1e0a-4c93-9626-a6aab22b666b', gatekeeper: 'f83777fa-1dc0-4163-aa84-ef501126d82b',
  notSure: '0c160182-e74d-4ace-9d3b-c4404043ef4b', exhausted: 'c1db8172-84bf-45a1-8f0e-5625157574a5' };
// Any open opportunity here blocks a re-screen, Manual Review included (a human is on it).
const KEVIN = ['O7LMZpDOFM2SYO65twC5', '1A1RkYaL93s2rqbQ3Opi', '9E6y34DlG1Imr8FV42RV', '3onA8GkJnSwgzIGTGSpI',
  'TwW6o0JdPXUlcwvX0EvI', 'smoNRUaagZYOElKFLwtp', 'OOu5TjgalfGZElEIoSbq'];
const F = { outcome: 'iTZa77JWntQs2QBuo9QU', verdict: 'boOwqb5qGOmbWBopWvTv', attempts: 'vcqKnq23gN5wIIHqRww4',
  date: 'MUkHW8R17PIksrSnpz6g', noise: 'AbbR6jH9PFMLJCRdCqMp' };
const BLOCK_USERS = ['ZU6NEmag5FFcYAYwtu75', 'QKMhxRVQX45dq2bxF5a5', 'u24gWdO3FlXhwjwhm6sE', 'hdIv63msJcYjhwfIJ4eg', 'T4p1bK3yo6Bl14OK1LP3',
  'nTHz8ZbvpMxoWqsyJsLs', 'u1v0arwCtQw8kr9FSYIT', '7KI79ZeuhHa1WrmFSaPH', 'j5w26gAQTznnaAgqRePi', 'QlDlzTUPYag7RxkJ2B5Q'];
const RESULT_TAGS = ['owner-confirmed', 'screen-busy', 'screen-quiet', 'screen-mismatch'];
const GHL = 'https://services.leadconnectorhq.com';
const DAY = 86400000;

const set = $('Settings').first().json;
const cid = String($('One contact').item.json.contact_id || '').trim();
const got = $('GHL: Get Contact').item.json;
const found = $('GHL: All Opps for Contact').item.json;
const s = v => String(v == null ? '' : v).trim();
const contact = (got && got.contact) || null;
const out = (action, reason, extra) => ({ json: Object.assign({ contact_id: cid, company: '', action, reason, age_days: null, ops: [] }, extra) });
if (!contact || !contact.id) return out('error', 'contact not readable: ' + s(got && got.error && (got.error.message || got.error.description)));
if (!found || found.error) return out('error', 'opportunity search failed');

const tags = (contact.tags || []).map(t => s(t).toLowerCase());
const cf = id => { const f = (contact.customFields || []).find(x => x.id === id); return f ? s(f.value) : ''; };
const company = s(contact.companyName) || s(contact.contactName) || cid;
const dateAge = d => /^\d{4}-\d{2}-\d{2}$/.test(d) ? Math.round((Date.parse(set.today_pt) - Date.parse(d)) / DAY) : null;
const tsAge = t => { const x = Date.parse(t); return isNaN(x) ? null : Math.floor((set.now_ms - x) / DAY); };
const isOpen = o => (o.status || 'open') === 'open';
const opps = found.opportunities || [];
const scr = opps.filter(o => o.pipelineId === SCREENER)
  .sort((a, b) => (isOpen(b) - isOpen(a)) || (Date.parse(b.updatedAt || 0) - Date.parse(a.updatedAt || 0)))[0] || null;
const openKevin = opps.filter(o => KEVIN.includes(o.pipelineId) && isOpen(o));
const age = dateAge(cf(F.date));
const stale = n => n !== null && n > set.stale_days;

const ops = [], notes = [];
const op = (label, method, url, body) => ops.push({ label, method, url, body });

// 1. Expire the hour-block marks.
const hourTags = tags.filter(t => t === 'owner-confirmed' || /^screened-pt-\d\d-\d\d$/.test(t));
const expire = hourTags.length > 0 && stale(age);
if (expire) {
  op('remove hour-block tags', 'DELETE', GHL + '/contacts/' + cid + '/tags', { tags: hourTags });
  // Only where the screener puts block followers: its own opportunity and Kevin's (never e.g. a demo pipeline).
  opps.filter(o => isOpen(o) && (o.pipelineId === SCREENER || KEVIN.includes(o.pipelineId))).forEach(o => op('remove block followers (' + (o.pipelineId === SCREENER ? 'screener' : 'Kevin') + ' opp)',
    'DELETE', GHL + '/opportunities/' + o.id + '/followers', { followers: BLOCK_USERS }));
} else if (hourTags.length && age === null) notes.push('owner-confirmed without a Date Screened: left alone');

// 2. Re-screen.
let why = '';
if (scr && isOpen(scr) && (scr.pipelineStageId === ST.gatekeeper || scr.pipelineStageId === ST.notSure) && stale(age))
  why = (scr.pipelineStageId === ST.gatekeeper ? 'Gatekeeper' : 'Not Sure') + ', screened ' + age + ' days ago';
else if (scr && isOpen(scr) && scr.pipelineStageId === ST.exhausted && stale(tsAge(scr.lastStageChangeAt)))
  why = 'Exhausted for ' + tsAge(scr.lastStageChangeAt) + ' days';
else if (scr && s(scr.status) === 'won' && stale(age))
  why = 'graduated owner, screened ' + age + ' days ago';
const blocked = !why ? '' : openKevin.length ? 'open opportunity in Kevin pipeline (re-screen trap)' : contact.dnd === true ? 'contact is DND' : '';
const rescreen = !!why && !blocked;
if (rescreen) {
  const body = { customFields: Object.values(F).map(id => ({ id, value: '' })) };
  if (set.screener_user_id) body.assignedTo = set.screener_user_id; else notes.push('no screener assigned');
  op('clear screener fields', 'PUT', GHL + '/contacts/' + cid, body);
  const drop = tags.filter(t => (RESULT_TAGS.includes(t) || /^screened-pt-\d\d-\d\d$/.test(t)) && !(expire && hourTags.includes(t)));
  if (drop.length) op('remove result tags', 'DELETE', GHL + '/contacts/' + cid + '/tags', { tags: drop });
  if (!tags.includes('screening')) op('add screening tag', 'POST', GHL + '/contacts/' + cid + '/tags', { tags: ['screening'] });
  op('screener opp -> Attempt 1 (open)', 'PUT', GHL + '/opportunities/' + scr.id, { pipelineId: SCREENER, pipelineStageId: ST.attempt1, status: 'open' });
  if (!(expire && isOpen(scr))) op('remove block followers (screener opp)', 'DELETE', GHL + '/opportunities/' + scr.id + '/followers', { followers: BLOCK_USERS });
}

const action = rescreen ? (expire ? 'expire+rescreen' : 'rescreen') : (expire ? 'expire' : 'none');
const reason = [why, blocked && 'not re-screened: ' + blocked].concat(notes).filter(Boolean).join(' | ');
return out(action, reason, { company, age_days: age, ops, scr_stage_changed_at: scr ? s(scr.lastStageChangeAt) : '' });

// All contacts decided: which requests to send this run. At most MAX_CONTACTS contacts are changed per
// run (the rest are reported and picked up tomorrow); a dry run sends nothing.
// A contact in screener_sweep_pending had an earlier sweep half fail (codex review): if nothing new is
// planned for it, its saved writes are replayed (they are all safe to repeat) — unless its screener
// opportunity moved after the failure, i.e. a newer call or dial happened: then replaying would undo
// that, so the saved writes are dropped and the lead is reported for a human.
const set = $('Settings').first().json;
const pending = new Map((() => { try { return $('Pending sweeps').all().map(i => i.json); } catch (e) { return []; } })()
  .filter(r => r && r.contact_id).map(r => [r.contact_id, r]));
const superseded = [];
const all = $input.all().map(i => i.json).map(d => {
  const p = pending.get(d.contact_id);
  if (!p || (d.ops || []).length || d.action === 'error') return d;
  if (d.scr_stage_changed_at && Date.parse(d.scr_stage_changed_at) > Date.parse(p.queued_at)) {
    superseded.push({ contact_id: d.contact_id, company: d.company, error: p.error });
    return d;
  }
  let ops = [];
  try { ops = JSON.parse(p.ops_json) || []; } catch (e) { ops = []; }
  return Object.assign({}, d, { action: 'retry', reason: 'finishing an earlier sweep that half failed (' + String(p.error || '').slice(0, 80) + ')', ops });
});
const acting = all.filter(d => (d.ops || []).length);
const now = acting.slice(0, set.max_contacts);
const brief = d => ({ contact_id: d.contact_id, company: d.company, action: d.action, reason: d.reason, age_days: d.age_days, requests: (d.ops || []).length });
return [{ json: {
  dry_run: set.dry_run === true,
  planned: now.map(brief),
  deferred: acting.slice(set.max_contacts).map(d => d.contact_id),
  blocked: all.filter(d => /not re-screened/.test(d.reason || '')).map(brief),
  errors: all.filter(d => d.action === 'error').map(brief),
  superseded,
  ops: set.dry_run === true ? [] : now.flatMap(d => d.ops.map(o => Object.assign({ contact_id: d.contact_id }, o)))
} }];

// What the sweep did (or would do, on a dry run). Reached from every path, including "no candidates".
// Also decides the screener_sweep_pending changes: a contact with any failed write is saved with all its
// writes (replayed next run); a pending contact that is now done, or superseded, is cleared.
const pick = n => { try { return $(n).all().map(i => i.json); } catch (e) { return null; } };
const set = (pick('Settings') || [{}])[0] || {};
const cand = (pick('Candidates') || [{}])[0] || {};
const plan = (pick('Plan Sweep') || [])[0] || { dry_run: false, planned: [], deferred: [], blocked: [], errors: [], superseded: [], ops: [] };
const pending = new Map((pick('Pending sweeps') || []).filter(r => r && r.contact_id).map(r => [r.contact_id, r]));
const sent = pick('Split Sweep Ops') || [];
const res = pick('GHL: Sweep Apply') || [];
const msg = r => String(r.error.message || JSON.stringify(r.error)).slice(0, 120);
const failedOps = sent.map((o, i) => ({ o, r: res[i] })).filter(x => !x.r || x.r.error);
const failed = failedOps.map(x => x.o.contact_id + ' ' + x.o.label + ': ' + (x.r ? msg(x.r) : 'no response'));
const failedContacts = new Set(failedOps.map(x => x.o.contact_id));
const done = plan.planned.filter(d => !failedContacts.has(d.contact_id));
const now = new Date().toISOString();
const pending_save = set.dry_run === true ? [] : [...failedContacts].map(cid => {
  const x = failedOps.find(f => f.o.contact_id === cid);
  const prev = pending.get(cid);
  return { contact_id: cid, ops_json: JSON.stringify(sent.filter(o => o.contact_id === cid).map(({ label, method, url, body }) => ({ label, method, url, body }))),
    error: x.o.label + ': ' + (x.r ? msg(x.r) : 'no response'), queued_at: now, first_failed_at: (prev && prev.first_failed_at) || now };
});
const pending_clear = set.dry_run === true ? [] : [...pending.keys()].filter(cid =>
  (done.some(d => d.contact_id === cid) || (plan.superseded || []).some(d => d.contact_id === cid)) && !failedContacts.has(cid));
return [{ json: {
  dry_run: set.dry_run === true,
  candidates: (cand.contact_ids || []).length,
  search_errors: cand.search_errors || [],
  truncated: cand.truncated || [],
  expired: done.filter(d => /expire/.test(d.action)),
  rescreened: done.filter(d => /rescreen/.test(d.action)),
  retried: done.filter(d => d.action === 'retry'),
  blocked: plan.blocked, errors: plan.errors, deferred: plan.deferred, superseded: plan.superseded || [], failed,
  pending_save, pending_clear
} }];

// screener_sweep_pending changes decided by Sweep Report: save half-failed contacts, clear finished ones.
const r = $input.first().json;
return (r.pending_save || []).map(p => ({ json: Object.assign({ op: 'save' }, p) }))
  .concat((r.pending_clear || []).map(contact_id => ({ json: { op: 'clear', contact_id } })));

// One count per screener stage for the daily summary (GHL returns meta.total with limit=1).
const BASE = 'https://services.leadconnectorhq.com/opportunities/search?location_id=rzaMhqeo2apNI1p6DG5z&pipeline_id=CvDwpavqkHSRhg5Bn3L4&status=open&limit=1&pipeline_stage_id=';
return [['Attempt 1', '7ff9193f-1e0a-4c93-9626-a6aab22b666b'], ['Attempt 2', 'd3d8862e-bc2e-443f-97e6-f77e577ac09e'],
  ['Attempt 3', 'abb54fb0-dbfc-44d9-aa21-796b91b7540b'], ['Attempt 4', 'ec53d2ba-8322-45d6-9d60-283cc4fc016e'],
  ['Owner Verified', 'c8e33d9d-fd1b-46f6-87a6-7cc47841642f'], ['Gatekeeper', 'f83777fa-1dc0-4163-aa84-ef501126d82b'],
  ['Not Sure', '0c160182-e74d-4ace-9d3b-c4404043ef4b'], ['Exhausted', 'c1db8172-84bf-45a1-8f0e-5625157574a5'],
  ['Disqualified', '65f9e1b4-8688-456d-845e-ebe0781101b9']].map(([name, id]) => ({ json: { name, url: BASE + id } }));

// The daily Slack summary (spec §10.2 item 7b): where the pipeline stands, the last 24 hours from the
// Supabase screener_log, what the stale sweep did, and anything that needs a human.
const DAY = 86400000, now = Date.now();
const pick = n => { try { return $(n).all().map(i => i.json); } catch (e) { return []; } };
const rep = pick('Sweep Report')[0] || {};
const names = pick('Stage count searches').map(j => j.name);
const counts = pick('GHL: stage counts').map((j, i) => ({ name: names[i], n: j && !j.error ? Number((j.meta && j.meta.total) != null ? j.meta.total : (j.opportunities || []).length) : null }));
const d24 = pick('Supabase: last 24h')[0] || {};
const rows = n => pick(n).filter(r => r && r.id);
const wb = rows('Failed write-backs').filter(r => now - Date.parse(r.received_at || r.createdAt) > 2 * DAY);
const grad = rows('Failed graduations').filter(r => now - Date.parse(r.first_failed_at || r.createdAt || r.at) > DAY);   // first failure, not the latest retry
const pend = rows('Pending log writes');
const n = x => (x == null || isNaN(Number(x)) ? 0 : Number(x));
const list = (a, f) => a.slice(0, 8).map(f).join(', ') + (a.length > 8 ? ' +' + (a.length - 8) + ' more' : '');
const today = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Los_Angeles' }).format(new Date(now));

const L = ['*Screener daily summary, ' + today + ' (PT)*' + (rep.dry_run ? '  _(dry run: nothing written)_' : '')];
L.push('*Pipeline now:* ' + counts.map(c => c.name + ' ' + (c.n == null ? '?' : c.n)).join(' · '));
const a1 = counts.find(c => c.name === 'Attempt 1');
if (a1 && a1.n === 0) L.push(':warning: *Attempt 1 is empty* — nothing new to dial: load the next set.');
if (d24.error || d24.calls === undefined) L.push('*Last 24 h:* Supabase not readable' + (d24.error ? ' (' + String(d24.error.message || '').slice(0, 80) + ')' : ''));
else {
  const pct = n(d24.compared) ? Math.round(100 * n(d24.matched) / n(d24.compared)) + '%' : 'n/a';
  L.push('*Last 24 h:* ' + n(d24.calls) + ' answered calls · ' + n(d24.owners) + ' Owner Verified · match ' + n(d24.matched) + '/' + n(d24.compared) + ' (' + pct + ') · '
    + n(d24.no_answers) + ' no-answers · ' + n(d24.voicemails) + ' voicemails · ' + n(d24.bad_numbers) + ' bad numbers');
}
const ex = rep.expired || [], rs = rep.rescreened || [];
L.push('*Stale sweep:* ' + ex.length + ' dropped from the hour lists · ' + rs.length + ' back to Attempt 1'
  + ((rep.retried || []).length ? ' · ' + rep.retried.length + ' earlier half-done sweeps finished' : '')
  + ((rep.blocked || []).length ? ' · ' + rep.blocked.length + ' not re-screened (open Kevin opportunity / DND)' : '')
  + ((rep.deferred || []).length ? ' · ' + rep.deferred.length + ' deferred to tomorrow' : ''));
if (rs.length) L.push('   re-screened: ' + list(rs, d => d.company));
if (rs.some(d => /no screener assigned/.test(d.reason || ''))) L.push(':warning: re-screened leads have no screener assigned (set SCREENER_USER_ID in the sweep settings).');

const human = [];
if ((rep.pending_save || []).length) human.push(rep.pending_save.length + ' leads half changed by the sweep (writes failed): retried tomorrow — ' + list(rep.pending_save, p => p.contact_id + ' (' + p.error + ')'));
if ((rep.superseded || []).length) human.push(rep.superseded.length + ' leads moved after a half-failed sweep, not replayed — check by hand: ' + list(rep.superseded, d => d.company || d.contact_id));
if ((rep.errors || []).length) human.push(rep.errors.length + ' contacts not readable: ' + list(rep.errors, d => d.contact_id));
if ((rep.search_errors || []).length) human.push('searches failed: ' + rep.search_errors.join('; '));
if ((rep.truncated || []).length) human.push('more than 100 leads in: ' + rep.truncated.join(', ') + ' (only the first 100 were swept)');
if (wb.length) human.push(wb.length + ' GHL write-backs failing for 48 h+: ' + list(wb, r => r.contact_name || r.contact_id));
if (grad.length) human.push(grad.length + ' graduations failing for a day+: ' + list(grad, r => r.contact_id + ' (' + String(r.reason || '').slice(0, 60) + ')'));
if (pend.length) human.push(pend.length + ' Supabase log writes pending (Screener: Log Retry replays them)');
L.push(human.length ? '*Needs a human:*\n• ' + human.join('\n• ') : '*Needs a human:* nothing :white_check_mark:');
return [{ json: { text: L.join('\n'), needs_human: human.length > 0 } }];
